DELETE FROM Language_en_US WHERE Tag='TXT_KEY_CWC2_GUIDE_THECONICALUNION' OR Tag GLOB 'TXT_KEY_CWC2_GUIDE_THECONICALUNION_*';
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC2_GUIDE_THECONICALUNION_CIV_HEADING_1','Playstyle and victory plan');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC2_GUIDE_THECONICALUNION_CIV_TEXT_1','The Conical Union[NEWLINE]Connected secondary cities and efficient worker logistics[NEWLINE]Science or conventional Domination[NEWLINE][NEWLINE]Develop useful non-capital cities, connect them through the actual native network, and make the connection worth its upkeep. The capital is the network anchor rather than a beneficiary of the signature connected-city yields.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC2_GUIDE_THECONICALUNION_CIV_HEADING_2','Opening priorities');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC2_GUIDE_THECONICALUNION_CIV_TEXT_2','Use Road Crews to improve food and resources before laying unnecessary roads. Settle defensible cities that can support the maintenance and benefit from a reliable connection to the capital.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC2_GUIDE_THECONICALUNION_CIV_HEADING_3','Develop the engine');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC2_GUIDE_THECONICALUNION_CIV_TEXT_3','Complete connections and put Detour Offices where their defense and conditional Gold matter. Check the native connection flag after changes. An extra route between already connected cities does not multiply the flat bonus.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC2_GUIDE_THECONICALUNION_CIV_HEADING_4','Convert the advantage');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC2_GUIDE_THECONICALUNION_CIV_TEXT_4','Use the network''s steady Production, Culture and Gold to support research and reinforcement. Protect bottlenecks and keep repair crews available so one raid does not disconnect a large part of the empire.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC2_GUIDE_THECONICALUNION_CIV_HEADING_5','Strengths');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC2_GUIDE_THECONICALUNION_CIV_TEXT_5','- Connected secondary cities receive steady development support.[NEWLINE]- Road Crews improve, connect and repair more effectively.[NEWLINE]- Offices combine normal Walls with additional cultural and network value.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC2_GUIDE_THECONICALUNION_CIV_HEADING_6','Weaknesses and costs');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC2_GUIDE_THECONICALUNION_CIV_TEXT_6','- The capital gains no UA connection yields.[NEWLINE]- Road upkeep and physical network defense remain real costs.[NEWLINE]- Flat bonuses do not multiply with redundant paths or automatically scale with Era.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC2_GUIDE_THECONICALUNION_CIV_HEADING_7','How to play against this civilization');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC2_GUIDE_THECONICALUNION_CIV_TEXT_7','- Pillage key connections and threaten exposed repair crews.[NEWLINE]- Attack the bottleneck that supports several cities rather than scattering raids.[NEWLINE]- Pressure a new city before its connection is active.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC2_GUIDE_THECONICALUNION_CIV_HEADING_8','Common mistakes');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC2_GUIDE_THECONICALUNION_CIV_TEXT_8','- Expecting a capital road loop to earn the non-capital bonus.[NEWLINE]- Counting several roads or Harbors as several copies of the same effect.[NEWLINE]- Assuming every route change is reflected immediately before the next economic settlement.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC2_GUIDE_THECONICALUNION_CIV_HEADING_9','Matchup examples - conditional analysis');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC2_GUIDE_THECONICALUNION_CIV_TEXT_9','Named custom-civilization matchups are conditional mechanical analysis, not tested win rates. All custom civs are human-only and multiplayer is unsupported; these comparisons are for theorycraft or explicitly configured scenarios, not ordinary random AI opponents. General counterplay applies to normal single-player games.[NEWLINE][NEWLINE]FAVOURABLE OPPORTUNITIES[NEWLINE][NEWLINE]Pigeon Republic: A protected native city-connection network supplies its own flat bonuses without consuming outgoing caravan capacity.[NEWLINE][NEWLINE]Saba: A well-connected network has opportunities on useful sites that lack Saba''s required River or Desert-centre conditions.[NEWLINE][NEWLINE]THREATS TO RESPECT[NEWLINE][NEWLINE]Beyond the Sky: Fast raiders can reach network bottlenecks and force repeated repair duty.[NEWLINE][NEWLINE]The Filthy Realm: Economic disruption and forced emergency spending make a maintenance-dependent network harder to sustain.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC2_GUIDE_THECONICALUNION_CIV_HEADING_10','Implementation and timing limits');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC2_GUIDE_THECONICALUNION_CIV_TEXT_10','Native connection status is cached. The documented first-settlement lag can apply after a network change; no instantaneous same-turn activation or removal is promised.');
