INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC2_GUIDE_THECONICALUNION_BACKGROUND','Develop useful non-capital cities, connect them through the actual native network, and make the connection worth its upkeep. The capital is the network anchor rather than a beneficiary of the signature connected-city yields.');
