INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC2_GUIDE_THECONICALUNION_LEADER_BACKGROUND','Develop useful non-capital cities, connect them through the actual native network, and make the connection worth its upkeep. The capital is the network anchor rather than a beneficiary of the signature connected-city yields.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) SELECT 'TXT_KEY_CWC2_GUIDE_THECONICALUNION_LEADER_BACKGROUND',Text FROM Language_en_US WHERE Tag='TXT_KEY_CONICAL_LEADER_PEDIA';
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC2_GUIDE_THECONICALUNION_STRATEGY','Develop useful non-capital cities, connect them through the actual native network, and make the connection worth its upkeep. The capital is the network anchor rather than a beneficiary of the signature connected-city yields.[NEWLINE][NEWLINE]Use Road Crews to improve food and resources before laying unnecessary roads. Settle defensible cities that can support the maintenance and benefit from a reliable connection to the capital.[NEWLINE][NEWLINE]Complete connections and put Detour Offices where their defense and conditional Gold matter. Check the native connection flag after changes. An extra route between already connected cities does not multiply the flat bonus.[NEWLINE][NEWLINE]Use the network''s steady Production, Culture and Gold to support research and reinforcement. Protect bottlenecks and keep repair crews available so one raid does not disconnect a large part of the empire.');
