INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC2_GUIDE_THECONICALUNION_LEADER_HEADING_2','Priorities and decisions');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC2_GUIDE_THECONICALUNION_LEADER_TEXT_2','Use Road Crews to improve food and resources before laying unnecessary roads. Settle defensible cities that can support the maintenance and benefit from a reliable connection to the capital.[NEWLINE][NEWLINE]Complete connections and put Detour Offices where their defense and conditional Gold matter. Check the native connection flag after changes. An extra route between already connected cities does not multiply the flat bonus.[NEWLINE][NEWLINE]Use the network''s steady Production, Culture and Gold to support research and reinforcement. Protect bottlenecks and keep repair crews available so one raid does not disconnect a large part of the empire.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC2_GUIDE_THECONICALUNION_LEADER_HEADING_3','Matchup examples - conditional analysis');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC2_GUIDE_THECONICALUNION_LEADER_TEXT_3','Named custom-civilization matchups are conditional mechanical analysis, not tested win rates. All custom civs are human-only and multiplayer is unsupported; these comparisons are for theorycraft or explicitly configured scenarios, not ordinary random AI opponents. General counterplay applies to normal single-player games.[NEWLINE][NEWLINE]FAVOURABLE OPPORTUNITIES[NEWLINE][NEWLINE]Pigeon Republic: A protected native city-connection network supplies its own flat bonuses without consuming outgoing caravan capacity.[NEWLINE][NEWLINE]Saba: A well-connected network has opportunities on useful sites that lack Saba''s required River or Desert-centre conditions.[NEWLINE][NEWLINE]THREATS TO RESPECT[NEWLINE][NEWLINE]Beyond the Sky: Fast raiders can reach network bottlenecks and force repeated repair duty.[NEWLINE][NEWLINE]The Filthy Realm: Economic disruption and forced emergency spending make a maintenance-dependent network harder to sustain.');
